{"command": "cd /testbed && /opt/miniconda3/envs/testbed/bin/python -m pytest -q xarray/tests/test_computation.py && /opt/miniconda3/envs/testbed/bin/python - <<'PY'
import numpy as np
import xarray as xr

cond = xr.DataArray([True, False], dims="x", attrs={"source": "cond"})
x = xr.DataArray([1, 2], dims="x", attrs={"source": "x"})
y = xr.DataArray([3, 4], dims="x", attrs={"source": "y"})

for keep_attrs, expected in [(True, {"source": "cond"}), (False, {}), (None, {})]:
    actual = xr.where(cond, x, y, keep_attrs=keep_attrs)
    assert actual.attrs == expected, (keep_attrs, actual.attrs)
    np.testing.assert_array_equal(actual.values, [1, 4])
print("DataArray cases OK")

ds_cond = xr.Dataset({"a": ("x", [True, False])}, attrs={"source": "cond"})
ds_x = xr.Dataset({"a": ("x", [1, 2])}, attrs={"source": "x"})
ds_y = xr.Dataset({"a": ("x", [3, 4])}, attrs={"source": "y"})
assert xr.where(ds_cond, ds_x, ds_y, keep_attrs=True).attrs == {"source": "cond"}
assert xr.where(ds_cond, ds_x, ds_y).attrs == {}
print("Dataset cases OK")

try:
    import dask.array as da
except ImportError:
    print("dask unavailable; skipped")
else:
    dask_x = xr.DataArray(da.from_array(np.array([1, 2]), chunks=1), dims="x", attrs={"source": "x"})
    actual = xr.where(cond, dask_x, 0, keep_attrs=True)
    assert actual.attrs == {"source": "cond"}
    assert hasattr(actual.data, "chunks")
    print("dask case OK")

with xr.set_options(keep_attrs=True):
    assert xr.where(cond, x, y).attrs == {"source": "cond"}
    assert xr.where(cond, x, y, keep_attrs=False).attrs == {}
with xr.set_options(keep_attrs=False):
    assert xr.where(cond, x, y, keep_attrs=True).attrs == {"source": "cond"}
print("global-option cases OK")
PY"}

